test('precedence, associativity and unary signs', () => {
  const cases = [
    ['1+2*3', 7],
    ['(1+2)*3', 9],
    ['2*3+4*5', 26],
    ['100/10/2', 5],
    ['100-10-2', 88],
    ['2^3^2', 512],
    ['(2^3)^2', 64],
    ['-2^2', -4],
    ['(-2)^2', 4],
    ['2^-2', 0.25],
    ['-2*3', -6],
    ['2*-3', -6],
    ['5--3', 8],
    ['--3', 3],
    ['+-3', -3],
    ['-+-3', 3],
    ['10%3', 1],
    ['-7%3', -1],
    ['7%-3', 1],
    ['2+3%2', 3],
    ['1/4', 0.25],
    ['  1  +  2  ', 3],
