    [{ op: 'test', path: '/a/y', value: [2, 1] }, /test failed at \/a\/y/],
    [{ op: 'test', path: '/a/x', value: '1' }, /test failed at \/a\/x/],
    [{ op: 'test', path: '/b', value: false }, /test failed at \/b/],
    [{ op: 'test', path: '/a', value: { x: 1 } }, /test failed at \/a/],
