test('bracket keys nest and empty brackets append', () => {
  const cases = [
    ['a[b]=1', { a: { b: '1' } }],
    ['a[b][c]=1', { a: { b: { c: '1' } } }],
    ['a[]=1&a[]=2', { a: ['1', '2'] }],
    ['a[0]=x&a[1]=y', { a: ['x', 'y'] }],
    ['a[1]=y&a[0]=x', { a: ['x', 'y'] }],
    ['a[0]=x&a[2]=y', { a: ['x', 'y'] }],
    ['a[b][]=1&a[b][]=2', { a: { b: ['1', '2'] } }],
    ['a[]=1&a[b]=2', { a: { 0: '1', b: '2' } }],
    ['a=1&a=2&a=3', { a: ['1', '2', '3'] }],
    ['a[01]=x', { a: { '01': 'x' } }],
    ['a[-1]=x', { a: { '-1': 'x' } }],
    ['a[b=1', { 'a[b': '1' } ],
