  const cases = [
    ['http://x/y?a=1&b=2', 'a=1&b=2'],
    ['http://x/y?a=1#frag', 'a=1'],
    ['http://x/y#frag?a=1', ''],
    ['http://x/y', ''],
    ['?a=1', 'a=1'],
