  const workspace = mkdtempSync(path.join(tmpdir(), 'plant-qs-'));
  try {
    cpSync(`${root}/test`, path.join(workspace, 'test'), { recursive: true });
    cpSync(`${root}/package.json`, path.join(workspace, 'package.json'));
