const root = '/tmp/claude-0/-home-user-deepseek-harness/f53f80cc-1f77-5d02-a862-99d59ffabdce/scratchpad/bench/e1/query-string';

const prompt = [
  '`src/query-string.js` is a finished reader and writer for URL query strings, and its test suite is failing. Find and fix the faults in the module. Keep every behaviour the passing tests already pin down, keep the exported names `parse`, `stringify` and `extract`, and do not weaken the module by special-casing the inputs the tests happen to use.',
  '`parse(input, options)` reads a query string, with or without a leading `?` or `#`, into an object. Pairs are separated by `&`, empty pairs are skipped, and each pair splits at its first unencoded `=`, with a missing `=` meaning an empty value. Keys and values are decoded separately: `+` stands for a space unless `options.plusAsSpace` is false, percent escapes are decoded, and text that cannot be decoded is kept as it is. A key is split into a path on its unencoded brackets before any decoding, so `a[b][c]` nests but an encoded bracket stays part of a name; `options.depth` (5 by default) limits how many bracket groups are structural, and whatever is left of the key becomes one final literal segment. Empty brackets append to the container, a repeated plain key collects its values into an array in order, and a container whose keys are all non-negative integers written without leading zeros becomes an array, ordered by index with missing indices dropped, as long as the largest index is below `options.arrayLimit` (20 by default). Every key is stored as an own property, so `__proto__` never reaches a prototype, and each call returns a result no earlier call can observe or influence.',
  "`stringify(input, options)` writes an object back. Members are written in insertion order, or ordered by their whole written key when `options.sort` is true, comparing by code unit. A nested object writes `a[b]=x`; an array writes `a[0]=x` by default, `a[]=x` under `arrayFormat: 'brackets'` and `a=x` under `arrayFormat: 'repeat'`; an empty array or object writes nothing. Strings, numbers and booleans become their text, `undefined` members are skipped, and a `null` member writes its key with no `=` at all unless `options.skipNull` is set, which drops it. Keys and values are percent-encoded, including `!'()*`, with structural brackets left literal and spaces written as `%20` or, under `space: 'plus'`, as `+`. `extract(url)` returns the text after the first `?` that comes before any `#`, or the empty string. Bad arguments throw `TypeError`.",
].join('\n\n');

writeFileSync(
  `${root}/task.json`,
  `${JSON.stringify(
    {
      id: 'code:query-string',
      tier: 4,
      domain: 'parsing',
      title: 'Repair a query-string reader and writer',
      prompt,
      heldOut: false,
      immutable: ['test', 'package.json'],
      checks: [
        { id: 'tests-pass', outcome: 'the test suite passes', run: 'node --test test/*.test.js' },
        { id: 'no-dependencies', outcome: 'no packages were installed', run: 'test ! -e node_modules' },
      ],
    },
    null,
    2,
  )}\n`,
);
console.log('wrote', `${root}/task.json`);

/**
 * Inline Markdown rendered to HTML: backslash escapes, code spans, autolinks,
 * inline links and emphasis.
 *
 * The renderer walks the text once. At each position it tries, in order, a
 * backslash escape, a code span, an autolink, an inline link and an emphasis
 * run; anything that does not start one of those is ordinary text.
 */

const ASCII_PUNCTUATION = /[!"#$%&'()*+,\-./:;<=>?@[\]\\^_`{|}~]/;
const WHITESPACE = /\s/;
const ALPHANUMERIC = /[A-Za-z0-9]/;
const HEX_PAIR = /^[0-9A-Fa-f]{2}$/;
const AUTOLINK_URI = /<([A-Za-z][A-Za-z0-9+.-]{1,31}:[^\s<>]*)>/y;
const AUTOLINK_EMAIL =
  /<([A-Za-z0-9.!#$%&'*+/=?^_`{|}~-]+@[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?(?:\.[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?)*)>/y;

/**
 * Escape the characters that cannot appear raw in HTML text or attributes.
 *
 * @param {string} text text to escape
 * @returns {string} the escaped text
 */
export function escapeHtml(text) {
  let out = '';
  for (const character of text) {
    if (character === '&') out += '&amp;';
    else if (character === '<') out += '&lt;';
    else if (character === '>') out += '&gt;';
    else if (character === '"') out += '&quot;';
    else out += character;
  }
  return out;
}

/**
 * Prepare a link destination for an `href` attribute.
 *
 * Existing percent-triplets are left alone; the characters that would end the
 * attribute or the URL are percent-encoded.
 *
 * @param {string} destination raw destination text
 * @returns {string} the attribute value
 */
function encodeDestination(destination) {
  let out = '';
  let i = 0;
  while (i < destination.length) {
    const character = destination[i];
    if (character === '%' && HEX_PAIR.test(destination.slice(i + 1, i + 3))) {
      out += destination.slice(i, i + 3);
      i += 3;
      continue;
    }
    if (character === ' ') out += '%20';
    else if (character === '"') out += '%22';
    else if (character === '<') out += '%3C';
    else if (character === '>') out += '%3E';
    else if (character === '\\') out += '%5C';
    else if (character === '`') out += '%60';
    else out += character;
    i += 1;
  }
  return escapeHtml(out);
}

/**
 * Resolve backslash escapes inside a destination or a title.
 *
 * @param {string} text raw text
 * @returns {string} the text with escaped punctuation unescaped
 */
function unescape(text) {
  let out = '';
  let i = 0;
  while (i < text.length) {
    if (text[i] === '\\' && text[i + 1] !== undefined && ASCII_PUNCTUATION.test(text[i + 1])) {
      out += text[i + 1];
      i += 2;
      continue;
    }
    out += text[i];
    i += 1;
  }
  return out;
}

/**
 * Measure the run of one character starting at a position.
 *
 * @param {string} text source text
 * @param {number} start index of the first character of the run
 * @returns {number} how many times the character repeats
 */
function runLength(text, start) {
  const character = text[start];
  let length = 0;
  while (text[start + length] === character) length += 1;
  return length;
}

/**
 * Read a code span opened at `start`.
 *
 * @param {string} text source text
 * @param {number} start index of the first backtick
 * @returns {{ html: string, end: number } | null} the rendered span, or null when the run never closes
 */
function codeSpan(text, start) {
  const length = runLength(text, start);
  let i = start + length;
  while (i < text.length) {
    if (text[i] !== '`') {
      i += 1;
      continue;
    }
    const closing = runLength(text, i);
    if (closing === length) {
      let content = text.slice(start + length, i);
      if (content.length >= 2 && content.startsWith(' ') && content.endsWith(' ') && content.trim() !== '') {
        content = content.slice(1, -1);
      }
      return { html: `<code>${escapeHtml(content)}</code>`, end: i + closing };
    }
    i += closing;
  }
  return null;
}

/**
 * Read an autolink opened at `start`.
 *
 * @param {string} text source text
 * @param {number} start index of the `<`
 * @returns {{ html: string, end: number } | null} the rendered link, or null when this is not an autolink
 */
function autolink(text, start) {
  AUTOLINK_URI.lastIndex = start;
  const uri = AUTOLINK_URI.exec(text);
  if (uri !== null) {
    return { html: `<a href="${encodeDestination(uri[1])}">${escapeHtml(uri[1])}</a>`, end: start + uri[0].length };
  }
  AUTOLINK_EMAIL.lastIndex = start;
  const email = AUTOLINK_EMAIL.exec(text);
  if (email !== null) {
    return {
      html: `<a href="mailto:${encodeDestination(email[1])}">${escapeHtml(email[1])}</a>`,
      end: start + email[0].length,
    };
  }
  return null;
}

/**
 * Find the `]` that closes the bracket at `start`.
 *
 * @param {string} text source text
 * @param {number} start index of the `[`
 * @returns {number} index of the closing bracket, or -1 when there is none
 */
function matchBracket(text, start) {
  let depth = 0;
  let i = start;
  while (i < text.length) {
    const character = text[i];
    if (character === '\\') {
      i += 2;
      continue;
    }
    if (character === '[') depth += 1;
    else if (character === ']') {
      depth -= 1;
      if (depth === 0) return i;
    }
    i += 1;
  }
  return -1;
}

/**
 * Read the destination and optional title of an inline link.
 *
 * @param {string} text source text
 * @param {number} start index just past the `(`
 * @returns {{ destination: string, title: string | null, end: number } | null} the parts, or null when malformed
 */
function linkTarget(text, start) {
  let i = start;
  while (i < text.length && WHITESPACE.test(text[i])) i += 1;

  let destination = '';
  if (text[i] === '<') {
    i += 1;
    let raw = '';
    while (i < text.length && text[i] !== '>') {
      if (text[i] === '<') return null;
      if (text[i] === '\\') {
        raw += text.slice(i, i + 2);
        i += 2;
        continue;
      }
      raw += text[i];
      i += 1;
    }
    if (text[i] !== '>') return null;
    i += 1;
    destination = unescape(raw);
  } else {
    let depth = 0;
    let raw = '';
    while (i < text.length) {
      const character = text[i];
      if (WHITESPACE.test(character)) break;
      if (character === '\\') {
        raw += text.slice(i, i + 2);
        i += 2;
        continue;
      }
      if (character === '(') depth += 1;
      if (character === ')') {
        if (depth === 0) break;
        depth -= 1;
      }
      raw += character;
      i += 1;
    }
    if (depth !== 0) return null;
    destination = unescape(raw);
  }

  while (i < text.length && WHITESPACE.test(text[i])) i += 1;

  let title = null;
  if (text[i] === '"' || text[i] === "'") {
    const quote = text[i];
    i += 1;
    let raw = '';
    while (i < text.length && text[i] !== quote) {
      if (text[i] === '\\') {
        raw += text.slice(i, i + 2);
        i += 2;
        continue;
      }
      raw += text[i];
      i += 1;
    }
    if (text[i] !== quote) return null;
    i += 1;
    title = unescape(raw);
    while (i < text.length && WHITESPACE.test(text[i])) i += 1;
  }

  if (text[i] !== ')') return null;
  return { destination, title, end: i + 1 };
}

/**
 * Read an inline link opened at `start`.
 *
 * @param {string} text source text
 * @param {number} start index of the `[`
 * @returns {{ html: string, end: number } | null} the rendered link, or null when this is not a link
 */
function inlineLink(text, start) {
  const close = matchBracket(text, start);
  if (close === -1 || text[close + 1] !== '(') return null;
  const target = linkTarget(text, close + 2);
  if (target === null) return null;
  const label = render(text.slice(start + 1, close), false);
  const title = target.title === null ? '' : ` title="${escapeHtml(target.title)}"`;
  return { html: `<a href="${encodeDestination(target.destination)}"${title}>${label}</a>`, end: target.end };
}

/**
 * Whether a delimiter run may open emphasis.
 *
 * @param {string} text source text
 * @param {number} start index of the run
 * @param {number} length length of the run
 * @param {string} marker `*` or `_`
 * @returns {boolean} true when the run can open
 */
function canOpen(text, start, length, marker) {
  const after = text[start + length];
  if (after === undefined || WHITESPACE.test(after)) return false;
  if (marker === '_') {
    const before = text[start - 1];
    if (before !== undefined && ALPHANUMERIC.test(before)) return false;
  }
  return true;
}

/**
 * Whether a delimiter run may close emphasis.
 *
 * @param {string} text source text
 * @param {number} start index of the run
 * @param {number} length length of the run
 * @param {string} marker `*` or `_`
 * @returns {boolean} true when the run can close
 */
function canClose(text, start, length, marker) {
  const before = text[start - 1];
  if (before === undefined || WHITESPACE.test(before)) return false;
  if (marker === '_') {
    const after = text[start + length];
    if (after !== undefined && ALPHANUMERIC.test(after)) return false;
  }
  return true;
}

/**
 * Read an emphasis run opened at `start`.
 *
 * @param {string} text source text
 * @param {number} start index of the first delimiter
 * @param {boolean} allowLinks whether links may be recognised inside
 * @returns {{ html: string, end: number } | null} the rendered emphasis, or null when the run does not open one
 */
function emphasis(text, start, allowLinks) {
  const marker = text[start];
  const length = runLength(text, start);
  if (!canOpen(text, start, length, marker)) return null;

  let i = start + length;
  while (i < text.length) {
    if (text[i] === '\\') {
      i += 2;
      continue;
    }
    if (text[i] !== marker) {
      i += 1;
      continue;
    }
    const closing = runLength(text, i);
    if (canClose(text, i, closing, marker)) {
      const use = Math.min(length, closing, 2);
      const inner = render(text.slice(start + use, i + closing - use), allowLinks);
      const tag = use === 2 ? 'strong' : 'em';
      return { html: `<${tag}>${inner}</${tag}>`, end: i + closing };
    }
    i += closing;
  }
  return null;
}

/**
 * Render one stretch of inline Markdown.
 *
 * @param {string} text source text
 * @param {boolean} allowLinks whether links may be recognised, false inside a link's own text
 * @returns {string} the rendered HTML
 */
function render(text, allowLinks) {
  let out = '';
  let i = 0;
  while (i < text.length) {
    const character = text[i];

    if (character === '\\') {
      const next = text[i + 1];
      if (next !== undefined && ASCII_PUNCTUATION.test(next)) {
        out += escapeHtml(next);
        i += 2;
        continue;
      }
      out += '\\';
      i += 1;
      continue;
    }

    if (character === '`') {
      const span = codeSpan(text, i);
      if (span !== null) {
        out += span.html;
        i = span.end;
        continue;
      }
      const length = runLength(text, i);
      out += '`'.repeat(length);
      i += length;
      continue;
    }

    if (character === '<') {
      const link = autolink(text, i);
      if (link !== null) {
        out += link.html;
        i = link.end;
        continue;
      }
    }

    if (character === '[' && allowLinks) {
      const link = inlineLink(text, i);
      if (link !== null) {
        out += link.html;
        i = link.end;
        continue;
      }
    }

    if (character === '*' || character === '_') {
      const span = emphasis(text, i, allowLinks);
      if (span !== null) {
        out += span.html;
        i = span.end;
        continue;
      }
      const length = runLength(text, i);
      out += character.repeat(length);
      i += length;
      continue;
    }

    out += escapeHtml(character);
    i += 1;
  }
  return out;
}

/**
 * Render inline Markdown to HTML.
 *
 * @param {string} markdown source text, one paragraph's worth of inline content
 * @returns {string} the rendered HTML
 */
export function renderInline(markdown) {
  if (typeof markdown !== 'string') throw new TypeError('markdown must be a string');
  return render(markdown, true);
}

import test from 'node:test';
import assert from 'node:assert/strict';

import { escapeHtml, renderInline } from '../src/markdown-inline.js';

/** Deterministic 32-bit PRNG so the generated cases are identical on every run. */
function mulberry32(seed) {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

test('ordinary text is escaped for HTML', () => {
  const cases = [
    ['', ''],
    ['plain text', 'plain text'],
    ['a < b & c > d', 'a &lt; b &amp; c &gt; d'],
    ['say "hi"', 'say &quot;hi&quot;'],
    ['&amp;', '&amp;amp;'],
    ['caf\u00e9 \u{1f600}', 'caf\u00e9 \u{1f600}'],
  ];
  for (const [input, expected] of cases) assert.equal(renderInline(input), expected, JSON.stringify(input));
  assert.equal(escapeHtml('<&">'), '&lt;&amp;&quot;&gt;');
  assert.throws(() => renderInline(null), TypeError);
});

test('backslash escapes remove markup meaning', () => {
  const cases = [
    ['\\*not em\\*', '*not em*'],
    ['\\_a\\_', '_a_'],
    ['\\`a\\`', '`a`'],
    ['\\[a\\](b)', '[a](b)'],
    ['\\\\', '\\'],
    ['\\\\*a*', '\\<em>a</em>'],
    ['\\a', '\\a'],
    ['a\\', 'a\\'],
    ['\\<', '&lt;'],
    ['\\&', '&amp;'],
  ];
  for (const [input, expected] of cases) assert.equal(renderInline(input), expected, JSON.stringify(input));
});

test('code spans close on a run of the same length', () => {
  const cases = [
    ['`code`', '<code>code</code>'],
    ['``a`b``', '<code>a`b</code>'],
    ['`` ` ``', '<code>`</code>'],
    ['``a`', '``a`'],
    ['`foo', '`foo'],
    ['a ` b', 'a ` b'],
    ['`*a*`', '<code>*a*</code>'],
    ['`a<b>&"`', '<code>a&lt;b&gt;&amp;&quot;</code>'],
    ['`a` and `b`', '<code>a</code> and <code>b</code>'],
    ['``a``b``', '<code>a</code>b``'],
  ];
  for (const [input, expected] of cases) assert.equal(renderInline(input), expected, JSON.stringify(input));
});

test('a code span drops at most one space from each end', () => {
  const cases = [
    ['` a `', '<code>a</code>'],
    ['`  a  `', '<code> a </code>'],
    ['` a`', '<code> a</code>'],
    ['`a `', '<code>a </code>'],
    ['`  `', '<code>  </code>'],
    ['` `', '<code> </code>'],
    ['` a b `', '<code>a b</code>'],
    ['`  ab  `', '<code> ab </code>'],
  ];
  for (const [input, expected] of cases) assert.equal(renderInline(input), expected, JSON.stringify(input));
});

test('emphasis pairs delimiter runs', () => {
  const cases = [
    ['*a*', '<em>a</em>'],
    ['_a_', '<em>a</em>'],
    ['**a**', '<strong>a</strong>'],
    ['__a__', '<strong>a</strong>'],
    ['***a***', '<strong><em>a</em></strong>'],
    ['*a* and *b*', '<em>a</em> and <em>b</em>'],
    ['**a** b **c**', '<strong>a</strong> b <strong>c</strong>'],
    ['*a_b*', '<em>a_b</em>'],
    ['**a *b* c**', '<strong>a <em>b</em> c</strong>'],
    ['*a * b*', '<em>a * b</em>'],
    ['a * b *', 'a * b *'],
    ['**a', '**a'],
    ['a**', 'a**'],
    ['*a**', '<em>a*</em>'],
    ['**a*', '<em>*a</em>'],
    ['* a *', '* a *'],
    ['*`a`*', '<em><code>a</code></em>'],
  ];
  for (const [input, expected] of cases) assert.equal(renderInline(input), expected, JSON.stringify(input));
});

test('an underscore inside a word is not emphasis', () => {
  const cases = [
    ['foo_bar_baz', 'foo_bar_baz'],
    ['foo*bar*baz', 'foo<em>bar</em>baz'],
    ['_foo_bar', '_foo_bar'],
    ['snake_case_name and _real_', 'snake_case_name and <em>real</em>'],
    ['a_b_ c', 'a_b_ c'],
    ['5_000_000', '5_000_000'],
    ['__a__b', '__a__b'],
    ['**a**b', '<strong>a</strong>b'],
  ];
  for (const [input, expected] of cases) assert.equal(renderInline(input), expected, JSON.stringify(input));
});

test('inline links carry a destination and an optional title', () => {
  const cases = [
    ['[x](/y)', '<a href="/y">x</a>'],
    ['[x](/y "t")', '<a href="/y" title="t">x</a>'],
    ["[x](/y 't')", '<a href="/y" title="t">x</a>'],
    ['[x]()', '<a href="">x</a>'],
    ['[**b**](/y)', '<a href="/y"><strong>b</strong></a>'],
    ['[a [b] c](/y)', '<a href="/y">a [b] c</a>'],
    ['[x](<a b>)', '<a href="a%20b">x</a>'],
    ['[x](/a(b)c)', '<a href="/a(b)c">x</a>'],
    ['[x](/a&b)', '<a href="/a&amp;b">x</a>'],
    ['[x](/y "a\\"b")', '<a href="/y" title="a&quot;b">x</a>'],
    ['[a](b)[c](d)', '<a href="b">a</a><a href="d">c</a>'],
    ['[a [b](/c) d](/e)', '<a href="/e">a [b](/c) d</a>'],
    ['[unclosed](/y', '[unclosed](/y'],
    ['[x](/a b)', '[x](/a b)'],
    ['[x]', '[x]'],
    ['[<b>](/y)', '<a href="/y">&lt;b&gt;</a>'],
  ];
  for (const [input, expected] of cases) assert.equal(renderInline(input), expected, JSON.stringify(input));
});

test('link destinations keep the escapes they already carry', () => {
  const cases = [
    ['[x](/a%20b)', '<a href="/a%20b">x</a>'],
    ['[x](/a%zzb)', '<a href="/a%zzb">x</a>'],
    ['[x](/100%25)', '<a href="/100%25">x</a>'],
    ['[x](/a"b)', '<a href="/a%22b">x</a>'],
    ['[x](/caf\u00e9)', '<a href="/caf\u00e9">x</a>'],
  ];
  for (const [input, expected] of cases) assert.equal(renderInline(input), expected, JSON.stringify(input));
});

test('autolinks cover absolute URIs and email addresses', () => {
  const cases = [
    ['<http://example.com/a>', '<a href="http://example.com/a">http://example.com/a</a>'],
    ['<http://x.com/?a=1&b=2>', '<a href="http://x.com/?a=1&amp;b=2">http://x.com/?a=1&amp;b=2</a>'],
    ['<mailto:x@y.com>', '<a href="mailto:x@y.com">mailto:x@y.com</a>'],
    ['<x@y.com>', '<a href="mailto:x@y.com">x@y.com</a>'],
    ['<a+b@example.com>', '<a href="mailto:a+b@example.com">a+b@example.com</a>'],
    ["<o'brien@x.co.uk>", '<a href="mailto:o\'brien@x.co.uk">o\'brien@x.co.uk</a>'],
    ['<first.last@sub.example.org>', '<a href="mailto:first.last@sub.example.org">first.last@sub.example.org</a>'],
    ['<not a link>', '&lt;not a link&gt;'],
    ['<div>', '&lt;div&gt;'],
    ['<@example.com>', '&lt;@example.com&gt;'],
    ['a < b', 'a &lt; b'],
    ['see <http://x.com> now', 'see <a href="http://x.com">http://x.com</a> now'],
  ];
  for (const [input, expected] of cases) assert.equal(renderInline(input), expected, JSON.stringify(input));
});

test('constructs combine without leaking markup', () => {
  const cases = [
    ['*[a](/b)*', '<em><a href="/b">a</a></em>'],
    ['[`a`](/b)', '<a href="/b"><code>a</code></a>'],
    ['`[a](/b)`', '<code>[a](/b)</code>'],
    ['**a `b` c**', '<strong>a <code>b</code> c</strong>'],
