        content = content.slice(1, -1);
      }`,
    to: `      let content = text.slice(start + length, i);
      if (content.trim() !== '') {
        content = content.trim();
      }`,
  },
  {
    group: 'intraword-underscore',
    from: `  const after = text[start + length];
  if (after === undefined || WHITESPACE.test(after)) return false;
  if (marker === '_') {
    const before = text[start - 1];
    if (before !== undefined && ALPHANUMERIC.test(before)) return false;
  }
  return true;`,
    to: `  const after = text[start + length];
  if (after === undefined || WHITESPACE.test(after)) return false;
