    to: "  /<([A-Za-z0-9.!#$%&'*/=?^_`{|}~-]+@",
  },
];

/**
 * Apply a set of edits to the correct module.
 *
 * @param {object[]} edits edits to apply
 * @returns {string} the edited source
 */
function build(edits) {
  let out = source;
  for (const edit of edits) {
    if (!out.includes(edit.from)) throw new Error(`anchor missing for ${edit.group}`);
    out = out.replace(edit.from, edit.to);
  }
  return out;
}

/**
 * Run the task's tests against one version of the module.
 *
 * @param {string} code module source to install as `src/markdown-inline.js`
 * @returns {number} the test runner's exit status
 */
function run(code) {
  const workspace = mkdtempSync(path.join(tmpdir(), 'plant-md-'));
  try {
    cpSync(`${root}/test`, path.join(workspace, 'test'), { recursive: true });
    cpSync(`${root}/package.json`, path.join(workspace, 'package.json'));
    cpSync(`${root}/reference/src`, path.join(workspace, 'src'), { recursive: true });
    writeFileSync(path.join(workspace, 'src', 'markdown-inline.js'), code);
    execFileSync('sh', ['-c', 'node --test test/*.test.js'], { cwd: workspace, stdio: 'pipe' });
    return 0;
  } catch (error) {
    return typeof error.status === 'number' ? error.status : 1;
  } finally {
    rmSync(workspace, { recursive: true, force: true });
  }
}

const groups = new Map();
for (const defect of defects) groups.set(defect.group, [...(groups.get(defect.group) ?? []), defect]);

if (run(build([])) !== 0) throw new Error('the correct module must pass');
for (const [id, edits] of groups) {
  const status = run(build(edits));
  console.log(`${id}: ${status === 0 ? 'NOT CAUGHT' : 'caught'}`);
  if (status === 0) process.exitCode = 1;
}

writeFileSync(`${root}/src/markdown-inline.js`, build(defects));
console.log(`planted ${groups.size} defects`);

