/**
 * Five-field cron expressions: parsing to explicit value sets, testing one
 * instant, and finding the next occurrence.
 *
 * Every calculation is in UTC, and the calendar arithmetic is done here rather
 * than through local-time conversions.
 */

/** Failure raised by every entry point in this module. */
export class CronError extends Error {
  /** @param {string} message reason */
  constructor(message) {
    super(message);
    this.name = 'CronError';
  }
}

const MONTH_NAMES = ['jan', 'feb', 'mar', 'apr', 'may', 'jun', 'jul', 'aug', 'sep', 'oct', 'nov', 'dec'];
const DAY_NAMES = ['sun', 'mon', 'tue', 'wed', 'thu', 'fri', 'sat'];
const DAYS_IN_MONTH = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
const SEARCH_YEARS = 5;

const FIELDS = [
  { key: 'minute', min: 0, max: 59, names: null, offset: 0 },
  { key: 'hour', min: 0, max: 23, names: null, offset: 0 },
  { key: 'dayOfMonth', min: 1, max: 31, names: null, offset: 0 },
  { key: 'month', min: 1, max: 12, names: MONTH_NAMES, offset: 1 },
  { key: 'dayOfWeek', min: 0, max: 7, names: DAY_NAMES, offset: 0 },
];

/**
 * Whether a Gregorian year has a 29th of February.
 *
 * @param {number} year full year
 * @returns {boolean} true for a leap year
 */
function isLeapYear(year) {
  return year % 4 === 0 && (year % 100 !== 0 || year % 400 === 0);
}

/**
 * How many days a month has.
 *
 * @param {number} year full year
 * @param {number} month month number, 1 to 12
 * @returns {number} the day count
 */
function daysInMonth(year, month) {
  return month === 2 && isLeapYear(year) ? 29 : DAYS_IN_MONTH[month - 1];
}

/**
 * The weekday of a date.
 *
 * @param {number} year full year
 * @param {number} month month number, 1 to 12
 * @param {number} day day of the month
 * @returns {number} 0 for Sunday through 6 for Saturday
 */
function weekday(year, month, day) {
  return new Date(Date.UTC(year, month - 1, day)).getUTCDay();
}

/**
 * Read one value of a field, resolving names.
 *
 * @param {string} token value text
 * @param {object} field field description
 * @returns {number} the numeric value
 */
function value(token, field) {
  const text = token.trim();
  if (text === '') throw new CronError(`empty value in ${field.key}`);
  if (field.names !== null && /^[A-Za-z]+$/.test(text)) {
    const index = field.names.indexOf(text.toLowerCase());
    if (index === -1) throw new CronError(`unknown name ${text} in ${field.key}`);
    return index + field.offset;
  }
  if (!/^\d+$/.test(text)) throw new CronError(`invalid value ${text} in ${field.key}`);
  const number = Number(text);
  if (number < field.min || number > field.max) {
    throw new CronError(`value ${text} is out of range ${field.min}-${field.max} in ${field.key}`);
  }
  return number;
}

/**
 * Read the step of a field term.
 *
 * @param {string} token step text
 * @param {object} field field description
 * @returns {number} the step
 */
function step(token, field) {
  if (!/^\d+$/.test(token) || Number(token) === 0) throw new CronError(`invalid step ${token} in ${field.key}`);
  return Number(token);
}

/**
 * Expand one comma-separated term of a field.
 *
 * @param {string} term term text
 * @param {object} field field description
 * @returns {number[]} the values the term stands for
 */
function expandTerm(term, field) {
  const [range, stepText, ...rest] = term.split('/');
  if (rest.length > 0) throw new CronError(`invalid term ${term} in ${field.key}`);
  const stride = stepText === undefined ? 1 : step(stepText, field);

  let start;
  let end;
  if (range === '*') {
    start = field.min;
    end = field.max;
  } else if (range.includes('-')) {
    const [from, to, ...extra] = range.split('-');
    if (extra.length > 0) throw new CronError(`invalid range ${range} in ${field.key}`);
    start = value(from, field);
    end = value(to, field);
    if (start > end) throw new CronError(`range ${range} is reversed in ${field.key}`);
  } else {
    start = value(range, field);
    end = stepText === undefined ? start : field.max;
  }

  const values = [];
  for (let current = start; current <= end; current += stride) values.push(current);
  return values;
}

/**
 * Expand one whole field.
 *
 * @param {string} text field text
 * @param {object} field field description
 * @returns {{ values: number[], restricted: boolean }} the sorted values and whether the field narrows anything
 */
function expandField(text, field) {
  if (text === '') throw new CronError(`empty ${field.key} field`);
  const values = new Set();
  for (const term of text.split(',')) {
    for (const found of expandTerm(term, field)) {
      values.add(field.key === 'dayOfWeek' && found === 7 ? 0 : found);
    }
  }
  return { values: [...values].sort((a, b) => a - b), restricted: text !== '*' };
}

/**
 * Parse a cron expression into explicit value sets.
 *
 * @param {string} expression five whitespace-separated fields
 * @returns {{ minute: number[], hour: number[], dayOfMonth: number[], month: number[], dayOfWeek: number[],
 *   restrictedDayOfMonth: boolean, restrictedDayOfWeek: boolean }} the parsed schedule
 */
export function parse(expression) {
  if (typeof expression !== 'string') throw new CronError('expression must be a string');
  const parts = expression.trim().split(/\s+/).filter((part) => part !== '');
  if (parts.length !== 5) throw new CronError(`expected 5 fields, got ${parts.length}`);

  const schedule = {};
  for (let i = 0; i < FIELDS.length; i += 1) {
    const field = FIELDS[i];
    const { values, restricted } = expandField(parts[i], field);
    schedule[field.key] = values;
    if (field.key === 'dayOfMonth') schedule.restrictedDayOfMonth = restricted;
    if (field.key === 'dayOfWeek') schedule.restrictedDayOfWeek = restricted;
  }
  return schedule;
}

/**
 * Whether a calendar day satisfies the two day fields.
 *
 * When both day fields are restricted a day matches if either one accepts it;
 * otherwise both must accept it, which the unrestricted field always does.
 *
 * @param {object} schedule parsed schedule
 * @param {number} year full year
 * @param {number} month month number, 1 to 12
 * @param {number} day day of the month
 * @returns {boolean} whether the day is scheduled
 */
function dayMatches(schedule, year, month, day) {
  const byMonthDay = schedule.dayOfMonth.includes(day);
  const byWeekday = schedule.dayOfWeek.includes(weekday(year, month, day));
  if (schedule.restrictedDayOfMonth && schedule.restrictedDayOfWeek) return byMonthDay || byWeekday;
  return byMonthDay && byWeekday;
}

/**
 * Check one instant against an expression.
 *
 * @param {string} expression cron expression
 * @param {Date} date instant to test, read in UTC with seconds ignored
 * @returns {boolean} whether the expression fires in that minute
 */
export function matches(expression, date) {
  const schedule = parse(expression);
  if (!(date instanceof Date) || Number.isNaN(date.getTime())) throw new CronError('date must be a valid Date');
  return (
    schedule.minute.includes(date.getUTCMinutes()) &&
    schedule.hour.includes(date.getUTCHours()) &&
    schedule.month.includes(date.getUTCMonth() + 1) &&
    dayMatches(schedule, date.getUTCFullYear(), date.getUTCMonth() + 1, date.getUTCDate())
  );
}

/**
 * Step to the first minute of the following month.
 *
 * @param {{ year: number, month: number }} at current position
 * @returns {{ year: number, month: number }} the following month
 */
function nextMonth({ year, month }) {
  return month === 12 ? { year: year + 1, month: 1 } : { year, month: month + 1 };
}

/**
 * Find the next occurrence at or after a calendar position.
 *
 * @param {object} schedule parsed schedule
 * @param {{ year: number, month: number, day: number, hour: number, minute: number }} at starting position
 * @param {number} limitYear last year the search may enter
 * @returns {object | null} the matching position, or null when the limit is reached
 */
function search(schedule, at, limitYear) {
  let { year, month, day, hour, minute } = at;
  for (;;) {
    if (year > limitYear) return null;

    if (!schedule.month.includes(month) || day > daysInMonth(year, month)) {
      ({ year, month } = nextMonth({ year, month }));
      day = 1;
      hour = 0;
      minute = 0;
      continue;
    }
    if (!dayMatches(schedule, year, month, day)) {
      day += 1;
      hour = 0;
      minute = 0;
      continue;
    }
    if (!schedule.hour.includes(hour)) {
      hour += 1;
      minute = 0;
      if (hour > 23) {
        hour = 0;
        day += 1;
      }
      continue;
    }
    if (!schedule.minute.includes(minute)) {
      minute += 1;
      if (minute > 59) {
        minute = 0;
        hour += 1;
        if (hour > 23) {
          hour = 0;
          day += 1;
        }
      }
      continue;
    }
    return { year, month, day, hour, minute };
  }
}

/**
 * Find the first occurrence strictly after an instant.
 *
 * @param {string} expression cron expression
 * @param {Date} from instant to start from, read in UTC
 * @returns {Date} the next matching minute, with zero seconds
 */
export function next(expression, from) {
  const schedule = parse(expression);
  if (!(from instanceof Date) || Number.isNaN(from.getTime())) throw new CronError('from must be a valid Date');

  const start = new Date(Math.floor(from.getTime() / 60000) * 60000 + 60000);
  const found = search(
    schedule,
    {
      year: start.getUTCFullYear(),
      month: start.getUTCMonth() + 1,
      day: start.getUTCDate(),
      hour: start.getUTCHours(),
      minute: start.getUTCMinutes(),
    },
    start.getUTCFullYear() + SEARCH_YEARS,
  );
  if (found === null) throw new CronError(`no occurrence within ${SEARCH_YEARS} years`);
  return new Date(Date.UTC(found.year, found.month - 1, found.day, found.hour, found.minute));
}

import test from 'node:test';
import assert from 'node:assert/strict';

import { CronError, matches, next, parse } from '../src/cron.js';

/** Deterministic 32-bit PRNG so the generated cases are identical on every run. */
function mulberry32(seed) {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const iso = (date) => date.toISOString();

test('a bare expression covers every value', () => {
  const schedule = parse('* * * * *');
  assert.equal(schedule.minute.length, 60);
  assert.equal(schedule.hour.length, 24);
  assert.deepStrictEqual(schedule.dayOfMonth, Array.from({ length: 31 }, (_, i) => i + 1));
  assert.deepStrictEqual(schedule.month, Array.from({ length: 12 }, (_, i) => i + 1));
  assert.deepStrictEqual(schedule.dayOfWeek, [0, 1, 2, 3, 4, 5, 6]);
  assert.equal(schedule.restrictedDayOfMonth, false);
  assert.equal(schedule.restrictedDayOfWeek, false);
});

test('lists, ranges and steps expand to sorted values', () => {
  const cases = [
    ['0 * * * *', 'minute', [0]],
    ['*/15 * * * *', 'minute', [0, 15, 30, 45]],
    ['2-20/5 * * * *', 'minute', [2, 7, 12, 17]],
    ['1-10/3 * * * *', 'minute', [1, 4, 7, 10]],
    ['5,3,1 * * * *', 'minute', [1, 3, 5]],
    ['1,1,2 * * * *', 'minute', [1, 2]],
    ['0,30 * * * *', 'minute', [0, 30]],
    ['55-59 * * * *', 'minute', [55, 56, 57, 58, 59]],
    ['0 9-17 * * *', 'hour', [9, 10, 11, 12, 13, 14, 15, 16, 17]],
    ['0 0/6 * * *', 'hour', [0, 6, 12, 18]],
    ['0 20/6 * * *', 'hour', [20]],
    ['0 0 1,15,31 * *', 'dayOfMonth', [1, 15, 31]],
    ['0 0 * 1,6-8 *', 'month', [1, 6, 7, 8]],
    ['0 0 * */3 *', 'month', [1, 4, 7, 10]],
  ];
  for (const [expression, field, expected] of cases) {
    assert.deepStrictEqual(parse(expression)[field], expected, expression);
  }
});

test('names are case-insensitive and Sunday has two numbers', () => {
  const cases = [
    ['0 0 * JAN,dec *', 'month', [1, 12]],
    ['0 0 * Feb-Apr *', 'month', [2, 3, 4]],
    ['0 0 * * MON-FRI', 'dayOfWeek', [1, 2, 3, 4, 5]],
    ['0 0 * * sun', 'dayOfWeek', [0]],
    ['0 0 * * SAT,SUN', 'dayOfWeek', [0, 6]],
    ['0 0 * * 7', 'dayOfWeek', [0]],
    ['0 0 * * 0,7', 'dayOfWeek', [0]],
    ['0 0 * * 5-7', 'dayOfWeek', [0, 5, 6]],
  ];
  for (const [expression, field, expected] of cases) {
    assert.deepStrictEqual(parse(expression)[field], expected, expression);
  }
});

test('only a bare asterisk leaves a day field unrestricted', () => {
  assert.equal(parse('0 0 13 * 5').restrictedDayOfMonth, true);
  assert.equal(parse('0 0 13 * 5').restrictedDayOfWeek, true);
  assert.equal(parse('0 0 * * 5').restrictedDayOfMonth, false);
  assert.equal(parse('0 0 13 * *').restrictedDayOfWeek, false);
  assert.equal(parse('0 0 */2 * *').restrictedDayOfMonth, true);
});

test('malformed expressions are rejected', () => {
  const cases = [
    ['* * * *', /expected 5 fields, got 4/],
    ['', /expected 5 fields, got 0/],
    ['* * * * * *', /expected 5 fields, got 6/],
    ['60 * * * *', /value 60 is out of range 0-59 in minute/],
    ['* 24 * * *', /value 24 is out of range 0-23 in hour/],
    ['0 0 0 * *', /value 0 is out of range 1-31 in dayOfMonth/],
    ['0 0 * 13 *', /value 13 is out of range 1-12 in month/],
    ['0 0 * * 8', /value 8 is out of range 0-7 in dayOfWeek/],
    ['0 0 * FOO *', /unknown name FOO in month/],
    ['0 0 * * FUN', /unknown name FUN in dayOfWeek/],
    ['\\*\\/0 * * * *', /invalid value/],
    ['*/0 * * * *', /invalid step 0 in minute/],
    ['5-1 * * * *', /range 5-1 is reversed in minute/],
    ['a * * * *', /invalid value a in minute/],
    ['0 0 * * MON-', /empty value in dayOfWeek/],
    ['1-2-3 * * * *', /invalid range 1-2-3 in minute/],
    ['1/2/3 * * * *', /invalid term 1\/2\/3 in minute/],
  ];
  for (const [expression, message] of cases) {
    assert.throws(() => parse(expression), message, expression);
  }
  assert.throws(() => parse(null), /expression must be a string/);
  assert.throws(() => parse(['*']), CronError);
});

test('matches ignores seconds and reads the date in UTC', () => {
  const at = new Date('2024-03-01T12:34:56.789Z');
  assert.equal(matches('* * * * *', at), true);
  assert.equal(matches('34 12 1 3 *', at), true);
  assert.equal(matches('35 12 1 3 *', at), false);
  assert.equal(matches('34 13 1 3 *', at), false);
  assert.equal(matches('34 12 * * FRI', at), true);
  assert.equal(matches('34 12 * * MON', at), false);
  assert.throws(() => matches('* * * * *', 'today'), /date must be a valid Date/);
  assert.throws(() => matches('* * * * *', new Date('nonsense')), /date must be a valid Date/);
});

test('a restricted day of month and day of week are combined with or', () => {
  assert.equal(matches('0 0 13 * 5', new Date('2024-08-13T00:00:00Z')), true);
  assert.equal(matches('0 0 13 * 5', new Date('2024-08-02T00:00:00Z')), true);
  assert.equal(matches('0 0 13 * 5', new Date('2024-08-14T00:00:00Z')), false);
  assert.equal(matches('0 0 13 * *', new Date('2024-08-02T00:00:00Z')), false);
  assert.equal(matches('0 0 * * 5', new Date('2024-08-13T00:00:00Z')), false);
  assert.equal(iso(next('0 0 13 * 5', new Date('2024-08-01T00:00:00Z'))), '2024-08-02T00:00:00.000Z');
});

test('next lands on the following occurrence, never on the start', () => {
  const cases = [
    ['* * * * *', '2024-03-01T00:00:00Z', '2024-03-01T00:01:00.000Z'],
    ['* * * * *', '2024-03-01T00:00:30Z', '2024-03-01T00:01:00.000Z'],
    ['* * * * *', '2024-03-01T23:59:00Z', '2024-03-02T00:00:00.000Z'],
    ['0 12 * * *', '2024-03-01T12:00:00Z', '2024-03-02T12:00:00.000Z'],
    ['0 12 * * *', '2024-03-01T11:59:59Z', '2024-03-01T12:00:00.000Z'],
    ['0 0 * * *', '2024-03-01T00:00:00.001Z', '2024-03-02T00:00:00.000Z'],
    ['*/15 * * * *', '2024-03-01T00:07:00Z', '2024-03-01T00:15:00.000Z'],
    ['*/15 * * * *', '2024-03-01T00:45:00Z', '2024-03-01T01:00:00.000Z'],
    ['30 4 * * 1', '2024-03-01T00:00:00Z', '2024-03-04T04:30:00.000Z'],
    ['0 0 * * 7', '2024-03-01T00:00:00Z', '2024-03-03T00:00:00.000Z'],
    ['0 0 1 * *', '2024-01-31T13:45:00Z', '2024-02-01T00:00:00.000Z'],
    ['0 0 31 * *', '2024-01-31T00:00:00Z', '2024-03-31T00:00:00.000Z'],
    ['0 0 1 1 *', '2024-06-15T00:00:00Z', '2025-01-01T00:00:00.000Z'],
    ['59 23 31 12 *', '2024-12-31T23:58:00Z', '2024-12-31T23:59:00.000Z'],
    ['0 0 29 2 *', '2024-03-01T00:00:00Z', '2028-02-29T00:00:00.000Z'],
    ['0 0 29 2 *', '2099-06-01T00:00:00Z', '2104-02-29T00:00:00.000Z'],
  ];
  for (const [expression, from, expected] of cases) {
    assert.equal(iso(next(expression, new Date(from))), expected, `${expression} from ${from}`);
  }
});

test('a schedule that never fires is reported', () => {
  assert.throws(() => next('0 0 30 2 *', new Date('2024-01-01T00:00:00Z')), /no occurrence within 5 years/);
