function run(code) {
  const workspace = mkdtempSync(path.join(tmpdir(), 'plant-cron-'));
  try {
    cpSync(`${root}/test`, path.join(workspace, 'test'), { recursive: true });
    cpSync(`${root}/package.json`, path.join(workspace, 'package.json'));
    cpSync(`${root}/reference/src`, path.join(workspace, 'src'), { recursive: true });
    writeFileSync(path.join(workspace, 'src', 'cron.js'), code);
    execFileSync('sh', ['-c', 'node --test test/*.test.js'], { cwd: workspace, stdio: 'pipe' });
    return 0;
  } catch (error) {
    return typeof error.status === 'number' ? error.status : 1;
  } finally {
    rmSync(workspace, { recursive: true, force: true });
  }
}

const groups = new Map();
for (const defect of defects) groups.set(defect.group, [...(groups.get(defect.group) ?? []), defect]);

